	private DataType createDataType(string name) {
		if (name.equals("int")) {
			return new IntegerDataType();
		}
		if (name.equals("char *")) {
			return new PointerDataType(new CharDataType());
		}
		if (name.equals("char *32")) {
			return new Pointer32DataType(new CharDataType());
		}
		if (name.equals("char * *32")) {
			return new Pointer32DataType(new PointerDataType(new CharDataType()));
		}
		return new StructureDataType(name, 2);
	}

	private FunctionSignature fun(string returnType, string name, params string[] args) {
		FunctionDefinitionDataType f = new FunctionDefinitionDataType(name);
		f.setReturnType(createDataType(returnType));
		ParameterDefinition[] @params = new ParameterDefinition[args.length / 2];
		for (int i = 0; i < @params.length; i++) {
			@params[i] =
				new ParameterDefinitionImpl(args[i * 2 + 1], createDataType(args[i * 2]), null);
		}
		f.setArguments(@params);
		return f;
	}


	internal class _Anon_DefaultDataTypeManagerService_1 : DefaultDataTypeManagerService
	{

			List<DataType> dtList; // assume types list will not change after requested during parse

			/* @Override */
			public List<DataType> getSortedDataTypeList() {
				if (dtList != null) {
					return dtList;
				}
				// Default implementation only provides builtIn types which is not consistent 
				// with Tool-based service.
				dtList = new(base.getSortedDataTypeList());
				program.getDataTypeManager().getAllDataTypes(dtList);
				Collections.sort(dtList, DataTypeComparator.INSTANCE);
				return dtList;
			}

			/* @Override */
			public DataType getDataType(string filterText) {
				return promptForDataType(filterText);
			}

			/* @Override */
			public DataType promptForDataType(string filterText) {
				// method only called if no results or multiple results were found.
				// Tool based implementation will prompt user, test will pick last one
				List<DataType> list = new();
				program.getDataTypeManager().findDataTypes(filterText, list);
				if (list.isEmpty()) {
					return null;
				}
				int count = list.size();
				assertTrue("Expected when required to choose from multiple types", count > 1);
				++dtChoiceCount;
				return list.get(count - 1);
			}
		
	}

